/* ПРИВЕТ, МИР — образец для авторов плагинов. Не делает ничего полезного,
   зато в одном файле показывает всё, из чего собирается плагин:

     панель с полями всех видов и условной видимостью;
     окно с кнопками и предпросмотром;
     диалоги (сообщение, вопрос, ввод, выбор);
     чтение и запись клеток, выделение области;
     свою группу на ленте и пункт в меню любой клетки;
     событие «приВыделении»;
     свою функцию для формул (ПРИВЕТ);
     картинку на лист (SVG прямо текстом).

   Смотреть лучше рядом с Документация/API-ПЛАГИНОВ.md. */

function Старт(){
  панель.список('языки', ['русский', 'english', 'deutsch']);
  панель.сообщение('Плагин запущен. Нажимайте кнопки — в журнале будет видно, что произошло.');
}

/* --- панель ---------------------------------------------------------------- */
function Показать(){
  const п = параметры({});
  панель.сообщение('Значения панели: ' + JSON.stringify(п));
}

function Место(){
  const в = книга.выделение;
  панель.список('сведения', [
    ['Лист', в.лист], ['Клетка', в.адрес], ['Область', в.область],
    ['Строк', в.r2 - в.r1 + 1], ['Столбцов', в.c2 - в.c1 + 1],
    ['Значение', String(ячейка(в.адрес).значение)],
  ]);
}

/* --- запись в книгу -------------------------------------------------------- */
function Написать(){
  const п = параметры({}), в = книга.выделение;
  ячейка(в.адрес).значение = 'Привет, ' + (п.имя || 'мир') + '!';
  ячейка(в.строка + 1, в.столбец).формула = 'ДЛСТР(' + в.адрес + ')';
  диапазон(в.адрес).выделить();
  панель.сообщение('Записал приветствие в ' + в.адрес + ' и формулу под ним');
}

/* --- диалоги --------------------------------------------------------------- */
async function Спросить(){
  const имя = await диалог.ввод('Как вас зовут?', 'мир');
  if(имя === null){ панель.сообщение('Отменено'); return; }
  const где = await диалог.выбор('Куда написать?', ['в клетку', 'в журнал']);
  if(где === null){ панель.сообщение('Отменено'); return; }
  if(где === 'в клетку'){
    if(await диалог.вопрос('Переписать ' + книга.выделение.адрес + '?'))
      ячейка(книга.выделение.адрес).значение = 'Привет, ' + имя + '!';
  } else панель.сообщение('Привет, ' + имя + '!');
}

/* --- окно ------------------------------------------------------------------ */
function ОкноОткрылось(){
  окно.список('цвета', ['синий', 'зелёный', 'красный']);
  окно.вид('образец', [
    {текст: 'Привет', цвет: '#2b5fd9', жирный: true},
    {текст: ', '},
    {текст: 'мир', цвет: '#1f9d55', курсив: true},
    {текст: '!'},
  ]);
  окно.сообщение('Это окно плагина. Форма в нём — та же, что в панели.');
}

function ОкноГотово(){
  const п = параметры({});
  панель.сообщение('Окно отдало: ' + JSON.stringify(п));
  ячейка(книга.выделение.адрес).значение = 'Привет, ' + (п.кому || 'мир') + '!';
}

/* --- картинка -------------------------------------------------------------- */
function Картинка(){
  const в = книга.выделение;
  картинка.вставить(
    '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 64 64" width="64" height="64">'
    + '<circle cx="32" cy="32" r="30" fill="#e6edfd" stroke="#2b5fd9" stroke-width="3"/>'
    + '<circle cx="23" cy="26" r="4" fill="#2b5fd9"/><circle cx="41" cy="26" r="4" fill="#2b5fd9"/>'
    + '<path d="M20 40c4 7 20 7 24 0" fill="none" stroke="#2b5fd9" stroke-width="3" stroke-linecap="round"/></svg>',
    {адрес: в.адрес, ширина: 64, высота: 64, имя: 'Привет'});
  панель.сообщение('Картинка положена на ' + в.адрес + '. «Отменить» её уберёт.');
}

/* --- событие --------------------------------------------------------------- */
function Ход(){
  const п = книга.повод;
  панель.поле('где', п.лист + '!' + п.адрес + (п.клеток > 1 ? ' (' + п.клеток + ' клеток)' : ''));
}

/* --- пункт меню ------------------------------------------------------------ */
function ИзМеню(){
  const п = книга.повод;
  панель.сообщение('Пункт «' + п.пункт + '» на клетке ' + п.адрес + ', значение: ' + String(п.значение));
}
